 static Color32[] ScreenData(RenderTexture rt){var old=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);tex.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);tex.Apply();var p=tex.GetPixels32();Object.Destroy(tex);RenderTexture.active=old;return p;}
 static async UniTask CompletionMenu(){completion=new CompletionReceipt{utc=DateTime.UtcNow.ToString("o")};await Pause(.5f);RecoveryShaderSupport.RequestRuntimeRefresh();RecoveryShaderSupport.BeginRendering();var materials=Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None).Where(r=>r.gameObject.scene.name=="IslandMenuBackdrop").SelectMany(r=>r.sharedMaterials).Where(m=>m&&CasinoShaderOwnership.Owns(m)).Distinct().ToArray();foreach(var m in materials){var compiled=RecoveryShaderSupport.CompiledFor(m.shader);if(compiled){completion.menuCustom++;if(m.shader!=compiled)completion.menuProxy++;}if(!m.shader||!m.shader.isSupported)completion.menuUnsupported++;completion.notes.Add("MENU "+m.name+" shader="+m.shader?.name+" native="+(compiled==m.shader));}if(materials.Length==0||completion.menuProxy>0||completion.menuUnsupported>0)completion.failures.Add("Menu casino material validation failed");var cam=SushiAndFish.FrontEnd.IslandFrontEndFlow.Active.OrbitCamera.GetComponent<Camera>();var rt=RenderTexture.GetTemporary(1440,900,24);try{RenderPipeline.SubmitRenderRequest(cam,new RenderPipeline.StandardRequest{destination=rt});var old=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(1440,900,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1440,900),0,0);tex.Apply();File.WriteAllBytes(Path.Combine(Reports,"screenshot-menu-current.png"),tex.EncodeToPNG());Object.Destroy(tex);RenderTexture.active=old;}finally{RenderTexture.ReleaseTemporary(rt);}CompleteStage("MENU");}
 static async UniTask RecordScreenAfterControl(ParkCasinoIntegration c,InteractableBase control){var pad=control.GetComponentInParent<Keypad>();if(!pad||!pad.keypadCamera.targetTexture)return;await Pause(.03f);string text=CasinoLabBootstrap.Field<TMPro.TextMeshPro>(pad,"displayText").text+"|"+pad.Network_errorMessage;var pixels=ScreenData(pad.keypadCamera.targetTexture);var q=new CompleteUpdate{game=pad.NetworkcasinoGame.GameType.ToString(),text=text,passed=true};if(previousPixels.TryGetValue(pad.GetInstanceID(),out var old)){q.expectedChange=old.Item1!=text;for(int i=0;i<pixels.Length;i++)if(pixels[i].r!=old.Item2[i].r||pixels[i].g!=old.Item2[i].g||pixels[i].b!=old.Item2[i].b)q.changedPixels++;q.passed=!q.expectedChange||q.changedPixels>4;}previousPixels[pad.GetInstanceID()]=(text,pixels);completion.updates.Add(q);if(!q.passed)completion.failures.Add("Screen did not redraw: "+q.game+" "+text);}
 static async UniTask CompletionFloor(ParkCasinoIntegration c,int floor){if(c.CurrentFloor==floor)return;var e=NetworkSingleton<ElevatorManager>.Instance;c.HostPlayer.TeleportPlayer(e.playerSpawnPosition.position-Vector3.up*(.4f*c.CurrentScale),true);await Pause(.5f);completion.notes.Add("ELEVATOR before: target="+floor+" lock="+e.IsLocked+" sourceFloor="+CasinoLabBootstrap.Field<int>(e,"_currentFloorIndex")+" host="+c.HostPlayer.transform.position+" proxy="+c.LogicInteractor.transform.position+" inHost="+e.IsInElevator(c.HostPlayer.transform.position+Vector3.up*(.4f*c.CurrentScale))+" inProxy="+e.IsInElevator(c.LogicInteractor.transform.position));foreach(var p in MonoSingleton<LocalManager>.Instance.players)completion.notes.Add("ELEVATOR logical player "+p.transform.position+" inside="+e.IsInElevator(p.transform.position));CompleteStage("ELEVATOR_REQUEST_"+floor);CasinoLabBootstrap.Field<List<Transform>>(e,"buttonList")[floor].GetComponent<InteractableEventTrigger>().ServerOnInteract(c.LogicInteractor);await Pause(.1f);await Pause(.2f);completion.notes.Add("ELEVATOR after: lock="+e.IsLocked+" sourceFloor="+CasinoLabBootstrap.Field<int>(e,"_currentFloorIndex")+" moving="+e.isTeleporting);CompleteStage("ELEVATOR_WAIT_"+floor);await Wait(()=>!e.isTeleporting&&c.CurrentFloor==floor&&c.Bootstrap.ready,35);await Pause(.4f);}
 static bool CompletionVisible(RawImage raw,Camera camera){var p=camera.WorldToViewportPoint(raw.transform.position);return raw.gameObject.activeInHierarchy&&raw.canvas.enabled&&p.z>camera.nearClipPlane&&p.x>0&&p.x<1&&p.y>0&&p.y<1;}
 static async UniTask CompletionSeats(ParkCasinoIntegration c){var player=c.HostPlayer;var seats=Object.FindObjectsByType<EmoteArea>(FindObjectsInactive.Include,FindObjectsSortMode.None).Where(a=>FullPath(a.transform).Contains("NativeAuditoriumSeats/")).OrderBy(a=>a.name).ToArray();foreach(var seat in seats){var q=new CompleteSeat{name=seat.name,spawned=seat.IsSpawned};completion.seats.Add(q);CompleteStage("SEAT_"+seat.name);try{var sphere=seat.GetComponent<SphereCollider>();var point=seat.transform.TransformPoint(sphere.center);foreach(var dir in new[]{seat.transform.forward,seat.transform.right,-seat.transform.right}){player.TeleportPlayer(seat.transform.position+dir*.8f+Vector3.up*.08f,true);player.FirstPersonCharacter.SetVelocity(Vector3.zero);await Pause(.1f);await Aim(c,point);await Pause(.1f);if(ReferenceEquals(CityExpansionInspection.Field<IBasicInteractable>(player.Interactor,"_currentBasicInteractable"),seat)){q.targeted=true;break;}}if(!q.targeted)throw new Exception("Native gaze did not select seat");await KeyE();await Pause(.25f);q.seated=player.IsUsingEmoteArea&&player.CurrentEmoteArea==seat&&seat.IsOccupied;q.poseError=Vector3.Distance(player.transform.position,CityExpansionInspection.Field<Vector3>(seat,"_targetPos"));var animator=CityExpansionInspection.Field<Animator>(player,"_tpsAnimator");q.animation=animator&&animator.GetBool(PaperPixelGames.Core.Player.PPG_Player.IS_EMOTE_STATIC);q.avatarVisible=animator&&animator.GetComponentsInChildren<SkinnedMeshRenderer>().Any(r=>r.enabled&&!r.forceRenderingOff&&(CasinoRuntimeContext.PlayerCamera.cullingMask&(1<<r.gameObject.layer))!=0);if(completion.seats.Count==1||completion.seats.Count==48)await Snapshot("screenshot-cinema-seated-"+completion.seats.Count+".png");player.EndStaticEmote();await Pause(.4f);q.released=!player.IsUsingEmoteArea&&!seat.IsOccupied;if(!q.seated||!q.released||q.poseError>.1f)throw new Exception("Seat state or pose failed");}catch(Exception ex){q.error=ex.Message;completion.failures.Add(seat.name+": "+ex.Message);if(player.IsUsingEmoteArea){player.EndStaticEmote();await Pause(.5f);}}}}
 static async UniTask CompletionThrow(){var action=Singleton<InputManager>.Instance.InputHandler.InputMap.asset.FindAction("Player/Throw");string binding=action.bindings.First(b=>b.effectivePath.StartsWith("<Keyboard>/")).effectivePath.Substring(11);var key=(UnityEngine.InputSystem.Key)Enum.Parse(typeof(UnityEngine.InputSystem.Key),binding,true);InputSystem.QueueStateEvent(keyboard,new KeyboardState(key));await Pause(.15f);InputSystem.QueueStateEvent(keyboard,new KeyboardState());await Pause(.5f);}
 static async UniTask CompletionPickup(ParkCasinoIntegration c,Item item,string origin){var q=new CompleteItem{type=item.GetType().Name,origin=origin};completion.items.Add(q);var bodies=item.GetComponentsInChildren<Rigidbody>();var constraints=bodies.Select(r=>r.constraints).ToArray();foreach(var r in bodies)r.constraints=RigidbodyConstraints.FreezeAll;try{await ReachControl(c,item);q.targeted=c.LogicInteractor.TargetInteractable==item;q.distance=Vector3.Distance(CasinoRuntimeContext.PlayerCamera.transform.position,item.transform.position);await PressActual(c,item);await Pause(.1f);var inv=c.LogicInteractor.GetComponent<PlayerInventory>();q.picked=inv.NetworkholdingItem==item;if(!q.picked)throw new Exception("E pickup failed");for(int bi=0;bi<bodies.Length;bi++)if(bodies[bi])bodies[bi].constraints=constraints[bi];if(item is Bat){InputSystem.QueueStateEvent(mouse,new MouseState{buttons=1});await Pause(.12f);q.used=CasinoLabBootstrap.Field<bool>(item,"_isUsing");InputSystem.QueueStateEvent(mouse,new MouseState());await Pause(.55f);}await CompletionThrow();q.thrown=inv.NetworkholdingItem!=item;if(!q.thrown)throw new Exception("Throw did not release item");}catch(Exception ex){q.error=ex.ToString();completion.failures.Add(q.type+": "+ex.Message);if(!c.LogicInteractor||!Mirror.NetworkServer.active)throw;}}
 static async UniTask CompletionRun(ParkCasinoIntegration c){try{city=new WorldPlayReceipt{utc=completion.utc};var accepted=JsonUtility.FromJson<CompletionReceipt>(File.ReadAllText(Path.Combine(Reports,SessionState.GetBool(Key+"resumeCompleteScreens",false)?"screenshot-all-screen-cases-complete.json":"screenshot-first-floor-layer-correct.json")));completion.screens=accepted.screens.Where(q=>q.actualButtons&&q.mask==2&&q.nearVisible&&q.midVisible&&(SessionState.GetBool(Key+"resumeCompleteScreens",false)?(SessionState.GetBool(Key+"remainingItemsOnly",false)||!(q.floor==4&&q.game=="Crash")):q.floor==1)).ToList();completion.updates=accepted.updates;if(SessionState.GetBool(Key+"remainingItemsOnly",false))completion.items=accepted.items.Where(q=>q.picked&&q.thrown&&string.IsNullOrEmpty(q.error)&&q.type!="PlayerCarry"&&q.type!="SleddingFrog").ToList();completion.notes.Add("Completed first-floor screen cases validated at "+accepted.utc);detailed=new InputReceipt{utc=completion.utc,ready=true};if(SessionState.GetBool(Key+"extraGameScreens",false)){await AddMissingGameScreens(c);return;}if(SessionState.GetBool(Key+"floor2diag",false)){await DumpFloorTwo(c);return;}c.HostEconomy.SetSavedGoldBalance(0,"10000000000",c.HostEconomy.ScrapBalance.Value);if(!SessionState.GetBool(Key+"skipCinema",false))await CompletionSeats(c);else{var previous=JsonUtility.FromJson<CompletionReceipt>(File.ReadAllText(Path.Combine(Reports,"screenshot-cinema-native-48.json")));completion.seats=previous.seats;completion.notes.Add("48 native E seat checks recorded in separate unchanged-seat run at "+previous.utc);}await CoastView(c,"followup-restaurant-corner",new Vector3(79,3.1f,-21),new Vector3(75.8f,5.6f,-17.3f));await CoastView(c,"followup-north-platform",new Vector3(9,3.1f,6.4f),new Vector3(3.8f,4,12));await CoastView(c,"followup-east-shore",new Vector3(108,3.1f,-45),new Vector3(120,3.3f,-20));await CoastView(c,"followup-south-corner",new Vector3(91,3.15f,-65),new Vector3(94,2.9f,-74));var verified=new HashSet<string>(completion.screens.Select(q=>q.game));
  for(int floor=1;floor<=5;floor++){await CompletionFloor(c,floor);CompleteStage("FLOOR_"+floor);var camera=CasinoRuntimeContext.PlayerCamera;var beforeSky=RenderSettings.skybox;var beforeFog=RenderSettings.fogColor;completion.notes.Add("FLOOR "+floor+" renderer="+camera.GetUniversalAdditionalCameraData().scriptableRenderer.GetType().Name+" original sky="+c.interiorSkybox?.name);foreach(var pad in c.ModuleRoot.GetComponentsInChildren<Keypad>(false).Where(k=>k.NetworkcasinoGame&&(SessionState.GetBool(Key+"resumeCompleteScreens",false)?!SessionState.GetBool(Key+"remainingItemsOnly",false)&&floor==4&&k.NetworkcasinoGame is Crash:floor!=1)).ToArray()){string type=pad.NetworkcasinoGame.GameType.ToString();CompleteStage("PAD_"+floor+"_"+type);await StandAtPad(c,pad.NetworkcasinoGame);c.RegisterCasinoButtons();pad.SendMessage("RequestRender",SendMessageOptions.DontRequireReceiver);await Pause(.1f);var pixels=ScreenData(pad.keypadCamera.targetTexture);previousPixels[pad.GetInstanceID()]=(CasinoLabBootstrap.Field<TMPro.TextMeshPro>(pad,"displayText").text+"|"+pad.Network_errorMessage,pixels);var q=new CompleteScreen{floor=floor,game=type,mask=pad.keypadCamera.cullingMask,brightPixels=pixels.Count(p=>p.a>20&&p.r+p.g+p.b>210),brightFraction=pixels.Count(p=>p.a>20&&p.r+p.g+p.b>210)/(float)pixels.Length};completion.screens.Add(q);if(verified.Add(type))await VerifyPad(c,pad);else{var controls=pad.GetComponentsInChildren<InteractableEventTrigger>(true);await RequiredPress(c,controls.First(b=>HasMethod(b,"ClearInput")));await RequiredPress(c,controls.First(b=>HasMethod(b,"SetBetMinimum")));}q.actualButtons=true;q.text=CasinoLabBootstrap.Field<TMPro.TextMeshPro>(pad,"displayText").text;var raw=CasinoLabBootstrap.Field<RawImage>(pad,"keypadRenderTarget");foreach(float distance in new[]{.85f,2.5f}){var point=pad.transform.position+pad.transform.forward*distance;point.y=NativeFloorHeight(c,point,pad.transform.position.y+.2f)+.06f;c.HostPlayer.TeleportPlayer(point,true);c.HostPlayer.FirstPersonCharacter.SetVelocity(Vector3.zero);await Pause(.15f);await Aim(c,raw.transform.position);q.supportChecked=true;q.playerFootY=c.HostPlayer.transform.position.y;q.expectedGround=NativeFloorHeight(c,point,pad.transform.position.y+.2f);q.grounded=FeetSupport(c)&&q.playerFootY>=q.expectedGround-.2f;bool visible=CompletionVisible(raw,camera);float eye=Vector3.Distance(camera.transform.position,raw.transform.position);if(distance<1){q.nearVisible=visible;q.nearDistance=eye;}else{q.midVisible=visible;q.midDistance=eye;}if(completion.screens.Count==1)await Snapshot("screenshot-keypad-"+(distance<1?"near":"mid")+".png");}if(q.brightPixels<10||q.brightFraction>.15f||q.mask!=2||!q.grounded||(camera.cullingMask&2)!=0||!q.nearVisible||!q.midVisible)completion.failures.Add("Near/mid screen visibility: "+floor+" "+type);}
   if(floor==1){foreach(var farPad in c.ModuleRoot.GetComponentsInChildren<Keypad>(false).Where(p=>p.NetworkcasinoGame)){if(completion.reach)break;var clear=farPad.GetComponentsInChildren<InteractableEventTrigger>(true).First(x=>HasMethod(x,"ClearInput"));var hit=clear.GetComponent<Collider>();foreach(float distance in new[]{3.35f,3.6f}){var far=farPad.transform.position+farPad.transform.forward*distance;far.y=NativeFloorHeight(c,far,farPad.transform.position.y+.2f)+.06f;var overlaps=Physics.OverlapCapsule(far+Vector3.up*.4f,far+Vector3.up*1.45f,.27f,~0,QueryTriggerInteraction.Ignore);if(overlaps.Any(x=>!x.transform.IsChildOf(c.HostPlayer.transform)))continue;c.HostPlayer.TeleportPlayer(far,true);c.HostPlayer.FirstPersonCharacter.SetVelocity(Vector3.zero);await Pause(.3f);await Aim(c,hit.bounds.center);float actual=Vector3.Distance(CasinoRuntimeContext.PlayerCamera.transform.position,hit.bounds.center);if(actual<3.1f)continue;var farPress=await PressActual(c,clear);completion.notes.Add("ACTUAL_REACH game="+farPad.NetworkcasinoGame.GameType+" distance="+actual+" reached="+farPress.reached+" invoked="+farPress.invoked);completion.reach=farPress.correct;if(completion.reach)break;}}await Snapshot("screenshot-casino-native-environment.png");var bats=c.ModuleRoot.GetComponentsInChildren<Bat>(false);completion.notes.Add("Native placed Bat count="+bats.Length);var bat=bats.FirstOrDefault(b=>b.IsInteractable);if(completion.items.Any(i=>i.type=="Bat"&&i.picked&&i.used&&i.thrown)){}else if(bat)await CompletionPickup(c,bat,"native floor 1");else{var prefab=CasinoResources.Load<GameObject>("Bat");if(prefab){var g=Object.Instantiate(prefab,NetworkSingleton<ElevatorManager>.Instance.playerSpawnPosition.position+new Vector3(0,.4f,-1),Quaternion.identity);foreach(var rb in g.GetComponentsInChildren<Rigidbody>())rb.isKinematic=true;Mirror.NetworkServer.Spawn(g);await Pause(.3f);await CompletionPickup(c,g.GetComponent<Bat>(),"isolated QA instance of native Bat prefab");Mirror.NetworkS